async function sourceIdentity(){
  const paths=execFileSync('rg',['--files','examples/browser-model-chat','modules/browser-rag-ts/src/application'],{cwd:productRoot,encoding:'utf8'}).split(/\r?\n/).filter(Boolean).map(path=>path.replaceAll('\\','/')).sort();
  const files=await Promise.all(paths.map(async path=>({path,sha256:digest(await readFile(join(productRoot,path)))})));
  const head=execFileSync('git',['rev-parse','HEAD'],{cwd:productRoot,encoding:'utf8'}).trim();
  if(before)assert.equal(head,'0225e4b5575e1d639abdf344b92d4fe0b98ec0f5');
  return{head,files:files.length,fingerprint:digest(JSON.stringify(files))};
}
